public class RedisTokenBucketRateLimiter {
    private final RedisTemplate<String, String> redisTemplate;
    private final long capacity;
    private final long refillRatePerSecond;

    public boolean allowRequest(String clientId) {
        String key = "rate_limit:" + clientId;
        String script = "local key = KEYS[1]\n" +
                        "local capacity = tonumber(ARGV[1])\n" +
                        "local refill = tonumber(ARGV[2])\n" +
                        "local now = tonumber(ARGV[3])\n" +
                        "local requested = tonumber(ARGV[4])\n" +
                        "local data = redis.call('hmget', key, 'tokens', 'last_updated')\n" +
                        "local tokens = tonumber(data[1])\n" +
                        "local last_updated = tonumber(data[2])\n" +
                        "if not tokens then\n" +
                        "    tokens = capacity\n" +
                        "    last_updated = now\n" +
                        "else\n" +
                        "    local delta = math.max(0, now - last_updated)\n" +
                        "    tokens = math.min(capacity, tokens + (delta * refill))\n" +
                        "    last_updated = now\n" +
                        "end\n" +
                        "if tokens < requested then\n" +
                        "    return 0\n" +
                        "end\n" +
                        "tokens = tokens - requested\n" +
                        "redis.call('hmset', key, 'tokens', tokens, 'last_updated', last_updated)\n" +
                        "redis.call('expire', key, 60)\n" +
                        "return 1";
        // Execute via Redis eval
        return true;
    }
}
